void Clk_Init(int count){
//reload the count value into systick reload value register
*pSYST_RVR &=~(0x00FFFFFF);
*pSYST_RVR |=(count);
//configure starting 3 bits to 1 of sysctick control status register
*pSYST_CSR |=(1<<0);
*pSYST_CSR |=(1<<1);
*pSYST_CSR |=(1<<2);





}
